import {HEALTH_QUIZ} from './health-quiz-data.js';
export function createHealthQuizState(){let index=0,selected=null,done=false;const reviewed=new Set();return{get question(){return HEALTH_QUIZ.questions[index];},choose(value){if(done||!Number.isInteger(value)||value<0||value>2)return false;selected=value;reviewed.add(index);return true;},retry(){if(done)return;selected=null;},next(){if(done||selected===null)return false;if(index===HEALTH_QUIZ.questions.length-1){done=true;return true;}index++;selected=null;return true;},reset(){index=0;selected=null;done=false;reviewed.clear();},snapshot:()=>({index,selected,done,correct:selected===null?null:selected===HEALTH_QUIZ.questions[index].correct,reviewed:reviewed.size})};}
export function openHealthQuiz(ui){const model=createHealthQuizState();return ui.workshop(HEALTH_QUIZ.title,`<p class="health-quiz-intro">손 씻기부터 물 마시기까지, 몸을 돌보는 선택을 골라봐요.</p><p id="health-quiz-count"></p><section id="health-quiz-question"><h3 id="health-quiz-prompt"></h3><div class="music-choices" id="health-quiz-choices"></div></section><p id="health-quiz-feedback" class="learning-feedback" role="status"></p><div class="school-tool-row"><button id="health-quiz-retry">다시 생각하기</button><button class="primary" id="health-quiz-next" disabled>다음 문제</button><button id="health-quiz-reset" hidden>처음부터 다시</button></div><details class="learning-source"><summary>이 상황의 근거 보기</summary><div id="health-quiz-sources"></div><p class="caption">공식 기관의 자료를 참고해 새로 만든 연습 문제예요. 기관이 제작하거나 인증한 퀴즈는 아니에요.</p></details><p class="caption">가상 상황 연습이며 진단·치료 안내가 아니에요. 개인 건강정보나 점수는 입력·저장하지 않아요.</p>`,()=>{let alive=true;const $=id=>document.querySelector('#'+id);function render(){if(!alive)return;const s=model.snapshot(),q=model.question;$('health-quiz-count').textContent=s.done?'8 / 8 · 모두 살펴봤어요':`${s.index+1} / 8`;$('health-quiz-question').hidden=s.done;$('health-quiz-reset').hidden=!s.done;$('health-quiz-retry').hidden=s.done;$('health-quiz-next').hidden=s.done;$('health-quiz-next').disabled=s.selected===null;$('health-quiz-next').textContent=s.index===7?'마치기':'다음 문제';if(s.done){$('health-quiz-feedback').textContent='여덟 가지 보건상식을 살펴봤어요. 오늘 해 볼 습관 하나를 떠올려 봐요!';return;}$('health-quiz-prompt').textContent=q.prompt;$('health-quiz-choices').replaceChildren();for(const[i,text]of q.choices.entries()){const b=document.createElement('button');b.textContent=text;b.setAttribute('aria-pressed',String(s.selected===i));b.onclick=()=>{if(!alive)return;model.choose(i);render();};$('health-quiz-choices').append(b);}$('health-quiz-feedback').textContent=s.selected===null?'천천히 선택해요. 틀려도 벌점 없이 다시 생각할 수 있어요':(s.correct?'좋아요. ':'다시 살펴볼까요? ')+q.feedback+(s.correct?'':' '+q.retry);$('health-quiz-sources').replaceChildren();for(const id of q.sources){const source=HEALTH_QUIZ.sources[id],p=document.createElement('p'),a=document.createElement('a');a.href=source.url;a.target='_blank';a.rel='noopener noreferrer';a.textContent=source.publisher+' · '+source.title;p.append(a);$('health-quiz-sources').append(p);}const where=document.createElement('p');where.textContent=q.sourceLocation;$('health-quiz-sources').append(where);}$('health-quiz-retry').onclick=()=>{if(!alive)return;model.retry();render();};$('health-quiz-next').onclick=()=>{if(!alive)return;model.next();render();};$('health-quiz-reset').onclick=()=>{if(!alive)return;model.reset();render();};render();return()=>{alive=false;};});}
